FUNCTION_BLOCK FB_Puerta
VAR_INPUT
    puertaAbierta : BOOL; // Entrada que indica si la puerta está abierta
    reset : BOOL; // Entrada para resetear el contador de aperturas
END_VAR

VAR_OUTPUT
    aviso : BOOL; // Salida que indica si se han acumulado 5 o más aperturas
    nAperturas : INT; // Salida que muestra el número de aperturas
END_VAR

VAR
    puertaAbiertaAnterior : BOOL; // Variable para almacenar el estado anterior de puertaAbierta
END_VAR

// Inicialización de variables
IF NOT puertaAbiertaAnterior THEN
    puertaAbiertaAnterior := puertaAbierta;
END_IF

// Lógica de reset
IF reset THEN
    nAperturas := 0;
    aviso := FALSE;
END_IF

// Contador de aperturas
IF puertaAbierta AND NOT puertaAbiertaAnterior THEN
    nAperturas := nAperturas + 1;
END_IF

// Actualización del estado anterior de puertaAbierta
puertaAbiertaAnterior := puertaAbierta;

// Lógica de aviso
IF nAperturas >= 5 THEN
    aviso := TRUE;
ELSE
    aviso := FALSE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Contador
VAR_INPUT
    sensorPieza : BOOL; // Contacto normalmente abierto sensor de pieza
    btnReset : BOOL; // Contacto normalmente abierto botón de reset
END_VAR

VAR_OUTPUT
    loteListo : BOOL; // Bobina que indica que el lote está listo
    cuenta : INT; // Variable que almacena el valor actual del contador
END_VAR

VAR
    C1 : CTU; // Contador ascendente
END_VAR

// Configuración del contador ascendente
C1.PV := 12; // Valor preestablecido del contador

// Rama 1: Conteo de piezas
IF sensorPieza THEN
    C1.CU := TRUE; // Alimenta la entrada de conteo
ELSE
    C1.CU := FALSE;
END_IF;

// Rama 2: Reset del contador
IF btnReset THEN
    C1.RESET := TRUE; // Alimenta la entrada de reset
ELSE
    C1.RESET := FALSE;
END_IF;

// Rama 3: Transferencia del valor del contador a la variable cuenta
cuenta := C1.CV; // Transfiere el valor actual del contador a la variable cuenta

// Rama 4: Control de la bobina loteListo
IF C1.Q THEN
    loteListo := TRUE; // Activa la bobina si el contador alcanza el valor preestablecido
ELSE
    loteListo := FALSE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilita la secuencia normal del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado     : INT;  (* Estado de la secuencia: 0=Verde, 1=Amarillo, 2=Rojo *)
    tFase      : TON; (* Temporizador de cada fase de la secuencia normal *)
    tBlink     : TP;  (* Temporizador de pulso para amarillo intermitente *)
    blink      : BOOL; (* Estado actual del parpadeo amarillo *)
    prevHab    : BOOL; (* Valor anterior de habilitado para detectar flancos *)
END_VAR

IF habilitado THEN
    (* --- Secuencia normal: Verde -> Amarillo -> Rojo -> (repite) --- *)

    (* Al detectar flanco ascendente de habilitado, reiniciar en verde *)
    IF NOT prevHab THEN
        estado := 0;
        tFase(IN := FALSE, PT := T#20S); (* Reset del temporizador *)
    END_IF;

    CASE estado OF

        0: (* VERDE: 20 segundos *)
            tFase(IN := TRUE, PT := T#20S);
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#20S); (* Reset *)
                estado := 1;
            END_IF;

        1: (* AMARILLO: 4 segundos *)
            tFase(IN := TRUE, PT := T#4S);
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#4S); (* Reset *)
                estado := 2;
            END_IF;

        2: (* ROJO: 15 segundos *)
            tFase(IN := TRUE, PT := T#15S);
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#15S); (* Reset *)
                estado := 0; (* Reinicia ciclo en verde *)
            END_IF;

        ELSE
            estado := 0; (* Estado invalido: volver a verde *)

    END_CASE;

    (* Asegurar que el temporizador de parpadeo quede inactivo *)
    tBlink(IN := FALSE, PT := T#1S);
    blink := FALSE;

ELSE
    (* --- Modo inhabilitado: amarillo intermitente 1s ON / 1s OFF --- *)

    (* Apagar verde y rojo *)
    luzV := FALSE;
    luzR := FALSE;

    (* Asegurar que el temporizador de secuencia quede inactivo *)
    tFase(IN := FALSE, PT := T#20S);

    (* Generar pulso de 1 segundo repetitivo para el parpadeo *)
    tBlink(IN := NOT tBlink.Q, PT := T#1S);

    (* El pulso activo indica amarillo encendido *)
    luzA := tBlink.Q;

END_IF;

(* Guardar estado actual de habilitado para deteccion de flanco en proximo ciclo *)
prevHab := habilitado;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilita la secuencia normal del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado     : INT;  (* Estado de la secuencia: 0=verde, 1=amarillo, 2=rojo *)
    tFase      : TON; (* Temporizador de cada fase normal *)
    tBlink     : TP;  (* Temporizador de pulso para amarillo intermitente *)
    bBlinkTrig : BOOL; (* Flanco para relanzar el pulso intermitente *)
END_VAR

IF habilitado THEN
    (* --- Secuencia normal: verde -> amarillo -> rojo -> verde --- *)

    CASE estado OF

        0: (* VERDE 20 s *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            tFase(IN := TRUE, PT := T#20S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#20S); (* Resetea temporizador *)
                estado := 1;
            END_IF;

        1: (* AMARILLO 4 s *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            tFase(IN := TRUE, PT := T#4S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#4S);
                estado := 2;
            END_IF;

        2: (* ROJO 15 s *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            tFase(IN := TRUE, PT := T#15S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#15S);
                estado := 0; (* Reinicia ciclo *)
            END_IF;

        ELSE
            estado := 0; (* Estado invalido: vuelve a verde *)

    END_CASE;

    (* Asegura que el temporizador de blink quede inactivo *)
    bBlinkTrig := FALSE;
    tBlink(IN := FALSE, PT := T#1S);

ELSE
    (* --- Modo inhabilitado: amarillo intermitente 1 s ON / 1 s OFF --- *)
    luzV := FALSE;
    luzR := FALSE;

    (* Relanza el pulso cada vez que expira *)
    tBlink(IN := bBlinkTrig, PT := T#1S);

    IF NOT tBlink.Q AND NOT bBlinkTrig THEN
        (* Pulso inactivo y no disparado: lanzar nuevo pulso *)
        bBlinkTrig := TRUE;
    END_IF;

    IF tBlink.Q THEN
        (* Pulso expirado: apagar disparo para permitir nuevo ciclo *)
        bBlinkTrig := FALSE;
    END_IF;

    luzA := tBlink.Q; (* Amarillo encendido durante el pulso activo *)

    (* Al rehabilitar, reinicia la secuencia en verde *)
    tFase(IN := FALSE, PT := T#20S);
    estado := 0;

END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilitacion del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    tCiclo : TON; (* Temporizador para el ciclo del semaforo *)
    tIntermitente : TON; (* Temporizador para el amarillo intermitente *)
    estado : INT; (* Estado del semaforo *)
END_VAR

(* Inicializacion de variables *)
IF NOT habilitado THEN
    (* Modo amarillo intermitente *)
    tIntermitente(IN := TRUE, PT := T#1S);
    luzV := FALSE;
    luzR := FALSE;
    luzA := tIntermitente.Q;
    tCiclo(IN := FALSE);
    estado := 0; (* Reiniciar estado al habilitar de nuevo *)
ELSE
    (* Modo ciclo normal del semaforo *)
    tIntermitente(IN := FALSE);
    CASE estado OF
        0: (* Luz verde *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            tCiclo(IN := TRUE, PT := T#20S);
            IF tCiclo.Q THEN
                estado := 1;
                tCiclo(IN := FALSE);
            END_IF
        1: (* Luz amarilla *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            tCiclo(IN := TRUE, PT := T#4S);
            IF tCiclo.Q THEN
                estado := 2;
                tCiclo(IN := FALSE);
            END_IF
        2: (* Luz roja *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            tCiclo(IN := TRUE, PT := T#15S);
            IF tCiclo.Q THEN
                estado := 0;
                tCiclo(IN := FALSE);
            END_IF
    END_CASE
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilitacion del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado      : INT;  (* Estado de la secuencia: 0=Verde, 1=Amarillo, 2=Rojo *)
    tFase       : TON;  (* Temporizador de fase normal *)
    tParpadeo   : TP;   (* Temporizador de pulso para amarillo intermitente *)
    bParpadeoOn : BOOL; (* Bandera de ciclo de parpadeo activo *)
END_VAR

IF NOT habilitado THEN
    (* --- Modo inhabilitado: amarillo intermitente 1s ON / 1s OFF --- *)
    estado := 0;        (* Reinicio de estado para cuando se habilite de nuevo *)
    tFase(IN := FALSE, PT := T#20S); (* Resetea temporizador de fase *)

    (* Genera el parpadeo usando TP: cada vez que Q baja, relanza el pulso *)
    tParpadeo(IN := NOT tParpadeo.Q AND NOT bParpadeoOn, PT := T#1S);

    (* Alterna entre encendido y apagado cada segundo *)
    IF tParpadeo.Q THEN
        bParpadeoOn := NOT bParpadeoOn;
    END_IF;

    luzV := FALSE;
    luzA := bParpadeoOn; (* Amarillo parpadea *)
    luzR := FALSE;

ELSE
    (* --- Modo habilitado: secuencia Verde -> Amarillo -> Rojo --- *)
    tParpadeo(IN := FALSE, PT := T#1S); (* Resetea temporizador de parpadeo *)
    bParpadeoOn := FALSE;

    CASE estado OF

        0: (* Verde durante 20 segundos *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            tFase(IN := TRUE, PT := T#20S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#20S); (* Resetea temporizador *)
                estado := 1;
            END_IF;

        1: (* Amarillo durante 4 segundos *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            tFase(IN := TRUE, PT := T#4S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#4S); (* Resetea temporizador *)
                estado := 2;
            END_IF;

        2: (* Rojo durante 15 segundos *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            tFase(IN := TRUE, PT := T#15S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#15S); (* Resetea temporizador *)
                estado := 0; (* Reinicia la secuencia en verde *)
            END_IF;

        ELSE
            estado := 0; (* Estado invalido: vuelve a verde *)

    END_CASE;

END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Llenado
VAR_INPUT
    nivelAlto : BOOL; (* Sensor de nivel alto *)
    nivelBajo : BOOL; (* Sensor de nivel bajo *)
    btnInicio : BOOL; (* Botón de inicio del proceso *)
    btnParo : BOOL;   (* Botón de paro del proceso *)
END_VAR
VAR_OUTPUT
    vLlenado : BOOL;  (* Válvula de llenado *)
    motorMezcla : BOOL; (* Motor de mezcla *)
    vDescarga : BOOL; (* Válvula de descarga *)
END_VAR
VAR
    estado : INT := 0; (* Estado del proceso: 0 = reposo, 1 = llenado, 2 = mezcla, 3 = descarga *)
    tMezcla : TON;     (* Temporizador para el motor de mezcla *)
END_VAR

(* Control del proceso de llenado por etapas *)
IF btnParo THEN
    (* Parar el proceso y llevar a estado seguro *)
    estado := 0;
    vLlenado := FALSE;
    motorMezcla := FALSE;
    vDescarga := FALSE;
ELSIF btnInicio THEN
    CASE estado OF
        0: (* Estado de reposo *)
            IF btnInicio THEN
                estado := 1; (* Iniciar llenado *)
            END_IF;
        1: (* Estado de llenado *)
            vLlenado := TRUE;
            IF nivelAlto THEN
                vLlenado := FALSE;
                estado := 2; (* Pasar a mezcla *)
                tMezcla(IN := TRUE, PT := T#60S);
            END_IF;
        2: (* Estado de mezcla *)
            motorMezcla := tMezcla.Q;
            IF NOT tMezcla.Q THEN
                estado := 3; (* Pasar a descarga *)
            END_IF;
        3: (* Estado de descarga *)
            vDescarga := TRUE;
            IF nivelBajo THEN
                vDescarga := FALSE;
                estado := 0; (* Volver a reposo *)
            END_IF;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Llenado
VAR_INPUT
    nivelAlto : BOOL;    // Sensor de nivel alto
    nivelBajo : BOOL;    // Sensor de nivel bajo
    btnInicio : BOOL;    // Botón de inicio
    btnParo   : BOOL;    // Botón de paro
END_VAR

VAR_OUTPUT
    vLlenado   : BOOL;   // Válvula de llenado
    motorMezcla: BOOL;   // Motor de mezcla
    vDescarga  : BOOL;   // Válvula de descarga
END_VAR

VAR
    estado     : INT;    // Estado del proceso
    timerMezcla: TON;    // Temporizador para el motor de mezcla
END_VAR

// Estados del proceso
// 0: Reposo
// 1: Llenado
// 2: Mezcla
// 3: Descarga

// Inicialización del bloque
IF NOT btnInicio THEN
    estado := 0;
END_IF

// Lógica de control del proceso
CASE estado OF
    0: // Reposo
        vLlenado := FALSE;
        motorMezcla := FALSE;
        vDescarga := FALSE;
        IF btnInicio THEN
            estado := 1;
        END_IF

    1: // Llenado
        vLlenado := TRUE;
        IF nivelAlto THEN
            vLlenado := FALSE;
            estado := 2;
            timerMezcla(IN := TRUE, PT := T#60S);
        END_IF

    2: // Mezcla
        motorMezcla := TRUE;
        timerMezcla(IN := TRUE);
        IF timerMezcla.Q THEN
            motorMezcla := FALSE;
            estado := 3;
        END_IF

    3: // Descarga
        vDescarga := TRUE;
        IF nivelBajo THEN
            vDescarga := FALSE;
            estado := 0;
        END_IF
END_CASE

// Lógica de paro de emergencia
IF btnParo THEN
    vLlenado := FALSE;
    motorMezcla := FALSE;
    vDescarga := FALSE;
    estado := 0;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Llenado
